create or replace function public.rental_search_records(p_query text,p_limit integer default 20)returns jsonb language plpgsql stable security definer set search_path='' as $$ declare q text:=lower(btrim(coalesce(p_query,'')));begin if auth.uid() is null or length(q)<2 then raise exception 'Enter at least two search characters';end if;return coalesce((select jsonb_agg(to_jsonb(x)order by x.rank desc,x.title)from(select * from(select 4 rank,'property' kind,p.id,p.name title,'/agent/rentals/properties/'||p.id href from public.rental_properties p where public.rental_branch_access(p.organisation_id,p.branch_id) and lower(p.name)like '%'||q||'%' union all select 3,'unit',u.id,u.unit_label,'/agent/rentals/properties/'||u.property_id from public.rental_units u where public.rental_branch_access(u.organisation_id,u.branch_id) and lower(u.unit_label)like '%'||q||'%' union all select 2,'vacancy',v.id,'Vacancy '||v.id::text,'/agent/rentals/vacancies/'||v.id from public.rental_vacancies v join public.rental_properties p on p.id=v.property_id where public.rental_branch_access(p.organisation_id,p.branch_id) and (lower(v.status)like '%'||q||'%' or v.id::text like q||'%') union all select 1,'tenancy',t.id,'Tenancy '||t.id::text,'/agent/rentals/tenancies/'||t.id||'/move-out' from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where public.rental_branch_access(p.organisation_id,p.branch_id) and (lower(t.status)like '%'||q||'%' or t.id::text like q||'%'))s order by rank desc,title limit greatest(1,least(p_limit,50)))x),'[]'::jsonb);end $$;
revoke all on function public.rental_search_records(text,integer)from public,anon;grant execute on function public.rental_search_records(text,integer)to authenticated;
